#!/usr/bin/env node
/**
 * Adds the system frameworks the Rust static library needs to the generated
 * Xcode project's link flags.
 *
 * Xcode performs the final link, not cargo: cargo produces `libapp.a` and the
 * app target links it. A crate that declares a framework from its build script
 * — `cargo:rustc-link-lib=framework=SystemConfiguration`, which is how
 * `objc2-system-configuration` and `system-configuration-sys` declare theirs —
 * only affects a link cargo itself drives. Building a staticlib drops the
 * directive, so Xcode never learns the framework is needed and the build fails
 * at `Ld` with a screen of undefined `_SC*` symbols that name no crate.
 *
 * `gen/apple/` is regenerated by `tauri ios init` and is gitignored, so this
 * has to run after every init, like the plist scripts beside it.
 *
 * Usage:
 *   node patch-xcode-frameworks.js
 */

const fs = require('fs');
const path = require('path');
const { ApplePaths } = require('./lib/apple-paths');

class XcodeFrameworks {
  // SystemConfiguration reaches the iOS build through iroh two ways, and both
  // arrived with iroh 1.1: netwatch 0.19.3 moved to netdev 0.46, whose
  // `os::ios::{dns, sc}` modules are on by default, and hickory-resolver reads
  // the system resolver through the same framework.
  static FRAMEWORKS = ['SystemConfiguration'];

  // Every buildSettings block, matched the same way ios-manual-signing.mjs
  // matches it. An OTHER_LDFLAGS list is parenthesised, never braced, so the
  // negated class still stops at the end of the block.
  static BLOCK = /buildSettings = \{([^}]*)\}/g;

  static LDFLAGS = /OTHER_LDFLAGS = (\([^)]*\)|"[^"]*"|[^;\n]+);/;

  /**
   * Ensures one buildSettings block links every wanted framework. Returns the
   * rewritten block and whether anything changed.
   */
  static settings(block) {
    const missing = XcodeFrameworks.FRAMEWORKS.filter((name) => !block.includes(name));

    if (missing.length === 0) {
      return { block, changed: false };
    }

    const flat = missing.map((name) => `-framework ${name}`).join(' ');
    const match = block.match(XcodeFrameworks.LDFLAGS);

    if (!match) {
      return { block: `${block}\t\t\t\tOTHER_LDFLAGS = "$(inherited) ${flat}";\n`, changed: true };
    }

    const value = match[1];

    // A list. Append the flags as their own elements, because Xcode splits a
    // list element on nothing: "-framework SystemConfiguration" as one element
    // reaches ld as a single unrecognised argument.
    if (value.startsWith('(')) {
      const items = missing.flatMap((name) => [`\t\t\t\t\t"-framework",`, `\t\t\t\t\t"${name}",`]);
      const appended = value.replace(/\)$/, `${items.join('\n')}\n\t\t\t\t)`);

      return { block: block.replace(match[0], `OTHER_LDFLAGS = ${appended};`), changed: true };
    }

    // A single string. Xcode splits this one on whitespace, so the flags go
    // inside the quotes rather than beside them.
    const quoted = value.startsWith('"');
    const inner = quoted ? value.slice(1, -1) : value;

    return {
      block: block.replace(match[0], `OTHER_LDFLAGS = "${inner} ${flat}";`),
      changed: true,
    };
  }

  /**
   * Rewrites a whole project.pbxproj. Every block rather than the app target's
   * alone: telling the targets apart means parsing the object graph, and the
   * flag is inert on a target that runs a script phase instead of linking.
   */
  static patch(pbx) {
    let blocks = 0;
    let changed = 0;

    const out = pbx.replace(XcodeFrameworks.BLOCK, (_match, inner) => {
      blocks += 1;

      const result = XcodeFrameworks.settings(inner);

      if (result.changed) changed += 1;

      return `buildSettings = {${result.block}}`;
    });

    return { pbx: out, blocks, changed };
  }

  static run() {
    const rootDir = path.resolve(__dirname, '../..');
    const target = ApplePaths.pbxproj(rootDir);

    const result = XcodeFrameworks.patch(fs.readFileSync(target, 'utf8'));

    // Loud, because a rewrite that matched nothing is indistinguishable from a
    // successful one until ld fails forty seconds into the build.
    if (result.blocks === 0) {
      console.error(`FAIL no buildSettings block was found in ${target}.`);
      console.error('      The project layout changed; this rewrite no longer applies.');
      process.exit(1);
    }

    fs.writeFileSync(target, result.pbx);

    console.log(`ok linked ${XcodeFrameworks.FRAMEWORKS.join(', ')}`);
    console.log(`   ${result.changed} of ${result.blocks} buildSettings blocks in ${target}`);
  }
}

module.exports = { XcodeFrameworks };

if (require.main === module) {
  XcodeFrameworks.run();
}
